export function createCart() {
  const items = [];
  return {
    add(name, price, quantity = 1) {
      if (price < 0) throw new RangeError('price must not be negative');
      items.push({ name, price, quantity });
    },
    total() {
      return items.reduce((sum, item) => sum + item.price * item.quantity, 0);
    },
    count() {
      return items.length;
    },
  };
}

import { describe, it, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import { createCart } from './cart.js';

describe('cart', () => {
  let cart;

  beforeEach(() => {
    cart = createCart();
  });

  it('starts empty', () => {
    assert.equal(cart.count(), 0);
    assert.equal(cart.total(), 0);
  });

  it('adds up prices times quantities', () => {
    cart.add('Dune', 9.5, 2);
    cart.add('Neuromancer', 7);
    assert.equal(cart.total(), 26);
  });

  it('rejects negative prices', () => {
    assert.throws(() => cart.add('Free lunch', -1), RangeError);
  });
});

import { test, mock } from 'node:test';
import assert from 'node:assert/strict';

function notifyOnLargeOrder(cart, notify) {
  if (cart.total() > 100) notify(`Large order: ${cart.total()}`);
}

test('notifies once for a large order', () => {
  const notify = mock.fn();
  const cart = { total: () => 250 };

  notifyOnLargeOrder(cart, notify);

  assert.equal(notify.mock.callCount(), 1);
  assert.deepEqual(notify.mock.calls[0].arguments, ['Large order: 250']);
});

import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import { once } from 'node:events';
import { app } from './app.js';

const server = app.listen(0);
await once(server, 'listening');
const base = `http://localhost:${server.address().port}`;

after(() => server.close());

test('GET /api/books returns the list', async () => {
  const response = await fetch(`${base}/api/books`);
  assert.equal(response.status, 200);
  const books = await response.json();
  assert.ok(Array.isArray(books));
  assert.equal(books[0].title, 'Dune');
});

test('GET /api/books/999 returns 404 with an error message', async () => {
  const response = await fetch(`${base}/api/books/999`);
  assert.equal(response.status, 404);
  assert.deepEqual(await response.json(), { error: 'Book not found' });
});
